---GetMonsterRareBgByMonsterClass
---@param monsterClass Constants.RoleClass
function CardUtils.GetMonsterRareBgByMonsterClass(monsterClass)
    local RoleClass = Constants.RoleClass
    local RareType = Constants.RareType
    local t = {
        [RoleClass.Creep] = -1,
        [RoleClass.Elite] = RareType.SR,
        [RoleClass.Boss] = RareType.SSR,
    }
