---SortCardBySortType 根据排序规则排序
---@param cards CardDojo[]
---@param sortType Constants.SortType
---@param asc boolean 是否是升序
function CardUtils.SortCardTrainBySortType(cards, sortType, asc, UIType)
    cards = checkTable(cards)
    local fieldNames
    if sortType == Constants.SortType.Rare then
        fieldNames = {"typePriority", "rare", "star", "cardLevel", "cardId"}
    elseif sortType == Constants.SortType.Star then
        fieldNames = {"typePriority", "star", "rare", "cardLevel", "cardId"}
    end
    if fieldNames then
        ---装备稀有度排序
        table.sort(cards, function(a, b)
            return CommonChecker(a, b, fieldNames, asc, {
                ["typePriority"] = true,
            })
        end)
    end
    return cards
end

---SortCardBySortType 根据排序规则排序
---@param cards CardDojo[]
---@param sortType Constants.SortType
---@param asc boolean 是否是升序
---@param UIType Constants.UISortType
---@param customParams table | nil @ 自定义参数
---@return CardDojo[]
function CardUtils.SortCardBySortType(cards, sortType, asc, UIType, customParams)
    cards = checkTable(cards)
    sortType = checkNumber(sortType)
    asc = checkBool(asc)
    UIType = checkNumber(UIType)

    local isCombatPower = sortType == Constants.SortType.CombatPower
    local t = {}
    --合成界面用排序表id区分出来
    if UIType == Constants.UISortType.Convert then
        t = cards
    else
        table.walk(cards, function(_, v)
            local cloneV = clone(v)
            --- 待优化
            if isCombatPower then
                if customParams and customParams.patrolMaze then
                    ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
                    local mazeAreaDojo      = customParams.patrolMaze.areaDojo
                    local mazeCardDojo      = mazeAreaDojo:GetMazeCard(cloneV.id)
                    local PatrolMazeUtils   = import('Game.UI.PatrolMaze.PatrolMazeUtils')
                    local ProgressionUtils  = import("Game.CardProgression.CardProgressionUtils")
                    local progressionEntity = ProgressionUtils.GenerateEntityByRobot(mazeCardDojo:GetCardDojo())
                    progressionEntity:FillPureCard(true)
                    if mazeCardDojo.isAssist then
                        local assistVo = PatrolMazeUtils.GetAssistCardVo(mazeCardDojo.assistId)
                        progressionEntity:FillAdditionMap(assistVo.additionMap)
                    end
                    cloneV.combatPower = FormulaUtils.CalcCardCombatEffectiveness(progressionEntity, nil, nil)
                else
                    cloneV.combatPower = FormulaUtils.GetCardFightingStrengthen(cloneV)
                end
            end
            local vo = cardConfMgr:GetCardByRefId(cloneV.cardId)
            if not isNull(vo) then
                cloneV.rare = vo.rare
                table.insert(t, cloneV)
            else
                printError(string.format("not exist setting %s", cloneV.cardId))
            end
        end)
    end
    local commonChecker = function(a, b, fieldNames, ascSortFlag)
        local fieldNameCount = #fieldNames
        local loopTimes = fieldNameCount - 1
        ascSortFlag = math.min(math.max(ascSortFlag or loopTimes, 1), loopTimes)
        for i = 1, fieldNameCount - 1 do
            local fieldName = fieldNames[i]
            local aFiled, bFiled = checkNumber(a[fieldName]), checkNumber(b[fieldName])
            
            if i <= ascSortFlag then
                if aFiled ~= bFiled then
                    if asc then
                        return aFiled > bFiled
                    else
                        return aFiled < bFiled
                    end
                end
            else
                if aFiled ~= bFiled then
                    return aFiled > bFiled
                end
            end

        end
        local fieldName = fieldNames[fieldNameCount]
        return checkNumber(a[fieldName]) > checkNumber(b[fieldName])
    end

    local fieldNames
    if UIType == Constants.UISortType.Convert then
        fieldNames = { "refId", "id"}
    elseif sortType == Constants.SortType.Quality or sortType == Constants.SortType.Rare then
        ---卡牌稀有度排序字段
        fieldNames = { "rare", "star", "cardLevel", "cardId" }
    elseif sortType == Constants.SortType.Level then
        ---卡牌等级排序字段
        fieldNames = { "cardLevel", "rare", "star", "cardId" }

    elseif sortType == Constants.SortType.Star then
        ---卡牌星级排序字段
        fieldNames = { "star", "cardLevel", "rare", "cardId" }

    elseif isCombatPower then
        ---卡牌武装值排序字段
        fieldNames = { "combatPower", "rare", "star", "cardLevel", "cardId" }
    end

    if fieldNames then
        table.sort(t, function(a, b)
            return commonChecker(a, b, fieldNames, 1)
        end)
    end

    return t
end

