                    progressionEntity:FillPureCard(true)
                    if mazeCardDojo.isAssist then
                        local assistVo = PatrolMazeUtils.GetAssistCardVo(mazeCardDojo.assistId)
                        progressionEntity:FillAdditionMap(assistVo.additionMap)
                    end
                    cloneV.combatPower = FormulaUtils.CalcCardCombatEffectiveness(progressionEntity, nil, nil)
                else
                    cloneV.combatPower = FormulaUtils.GetCardFightingStrengthen(cloneV, nil, checkNumber(cloneV.id) <= 0)
                end
            end
            local vo = cardConfMgr:GetCardByRefId(cloneV.cardId)
            if not isNull(vo) then
                cloneV.rare = vo.rare
                table.insert(t, cloneV)
            else
                printError(string.format("not exist setting %s", cloneV.cardId))
            end

            index = index + 1
        end)
    end

    local commonChecker = function(a, b, fieldNames, ascSortFlag)
        local fieldNameCount = #fieldNames
        local loopTimes = fieldNameCount - 1
        ascSortFlag = math.min(math.max(ascSortFlag or loopTimes, 1), loopTimes)
        for i = 1, fieldNameCount - 1 do
            local fieldName = fieldNames[i]
            local aFiled, bFiled = checkNumber(a[fieldName]), checkNumber(b[fieldName])
            if i <= ascSortFlag then
                if aFiled ~= bFiled then
                    if asc then
                        return aFiled > bFiled
                    else
                        return aFiled < bFiled
                    end
                end
            else
                if aFiled ~= bFiled then
                    return aFiled > bFiled
                end
            end

        end
        local fieldName = fieldNames[fieldNameCount]
        return checkNumber(a[fieldName]) > checkNumber(b[fieldName])
    end

    local fieldNames
    if UIType == Constants.UISortType.Convert then
        fieldNames = { "refId", "id"}
    elseif sortType == Constants.SortType.Quality or sortType == Constants.SortType.Rare then
        ---卡牌稀有度排序字段
        fieldNames = { "rare", "star", "cardLevel", "cardId" }
    elseif sortType == Constants.SortType.Level then
        ---卡牌等级排序字段
        fieldNames = { "cardLevel", "rare", "star", "cardId" }

    elseif sortType == Constants.SortType.Star then
        ---卡牌星级排序字段
        fieldNames = { "star", "cardLevel", "rare", "cardId" }

    elseif isCombatPower then
        ---卡牌武装值排序字段
        fieldNames = { "isUp", "usable", "combatPower", "rare", "star", "cardLevel", "cardId" }
    end

    if fieldNames then
        table.sort(t, function(a, b)
            return commonChecker(a, b, fieldNames, 1)
        end)
    end

    return t
end

