---InitMonsterSkillData
---初始化怪物技能数据
---@param monsterTypeVo MonsterTypeVo
---@param isNotShowPassive boolean 是否显示被动，默认显示
function CardUtils.InitMonsterSkillData(monsterTypeVo, isNotShowPassive)
    ---@type UIBattlingTools
    local UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")
    local isRole        = checkNumber(monsterTypeVo.role) > 0
    local monsterSkillData = {}
    local atkSkillIdList, spSkillId
    if isRole then
        local skinId = monsterTypeVo.skinId
        ---@type CardVo
        local cardVo     = cardConfMgr:GetCardBySkinRefId(skinId)
        local skillNode  = cardVo.skillNode
        spSkillId        = skillNode.finalSkill
        atkSkillIdList = {
            skillNode.generalSkill, skillNode.advancedSkill
        }
    else
        spSkillId        = monsterTypeVo.hitSkill
        atkSkillIdList = {
            monsterTypeVo.atkSkill, monsterTypeVo.atkSkill2, monsterTypeVo.atkSkill3,
            monsterTypeVo.atkSkill4, monsterTypeVo.atkSkill5, monsterTypeVo.atkSkill6
        }
    end
    ---@type SkillCardVo
    local vo = UIBattlingTools.GetSkillCardInfoByTwoParam(spSkillId)
    local skillDescList = CardUtils.ParseSkillDescBySkillId(spSkillId, 1, 1, 1)
    local skillDesc = table.concat(skillDescList)
    table.insert(monsterSkillData, {isSp = true, titleName = vo.skillName, desc = skillDesc})

    --- 怪物写死1星描述
    for i, skillId in ipairs(atkSkillIdList) do
        if checkNumber(skillId) > 0 then
            ---@type SkillCardVo
            local skillVo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId)
            local skillName = skillVo.skillName
            local desc = table.concat(CardUtils.ParseSkillDescBySkillId(skillId, 1))
            table.insert(monsterSkillData, {titleName = skillName, desc = desc, skillTypeName = localize("主动")})
        end
    end

    if not isNotShowPassive then
        local effectIds = parse_strings(monsterTypeVo.showPassive)
        local CardProgressionSkillUtils = import("Game.CardProgression.CardProgressionSkillUtils")
        for i, effectId in ipairs(effectIds) do
            if checkNumber(effectId) > 0 then
                local buffRow = CfUtils.GetCfLine(AutoIds.IdSetting573, effectId)
                if checkNumber(buffRow:Get("showDesc")) > 0 then
                    local titleName, desc = CardProgressionSkillUtils.ParseSkillBuffDesc(effectId)
                    table.insert(monsterSkillData, {titleName = titleName, desc = desc, skillTypeName = localize("被动")})
                end
            end
        end
    end
    return monsterSkillData
end

---ParseSkillDesc
---@param skillId number           技能id
---@param skillStar number         技能星级
---@return table skillDescInfo<star, desc>
---@return table skillOtherDescInfo<star, table<index, {name, skillDesc}>>>
function CardUtils.ParseSkillDescBySkillId(skillId, skillStar, curSkillStar, rare, isSpecial, finalSkillLevel)
    -------------------------
    --- 获取技能描述的方式
    --- 1. 普通技能
    --- 传几星就是 skillDesc几
    --- 2. 大招
    ---  skillDesc 1-skillStarMax 的拼接
    ---@type CardProgressionSkillUtils
    local CardProgressionSkillUtils = import("Game.CardProgression.CardProgressionSkillUtils")

    ---@type UIBattlingTools
    local UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")
    ---@type SkillCardVo
    local vo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId)

    --local skillInfo = cardConfMgr:GetSkillByRefId(skillId)
    local skillType = vo.skillType
    local isFinal = skillType == Constants.CardSkillType.FinalSkill
    ----------
    local skillDescInfo = CardProgressionSkillUtils.ParseSkillDesc(vo, skillStar, isFinal, curSkillStar, isSpecial, rare, nil, nil, finalSkillLevel)
    return skillDescInfo
end


