function CardUtils.CalcCatHouseHandbookAttrId2Num(unlockGenes)
    unlockGenes = checkTable(unlockGenes)
    local checkNumber = checkNumber
    ---@type BaseSetting
    local setting     = CfUtils.GetCf(AutoIds.IdSetting1902, "CatHouseCatDataVo")
    local attrId2Num  = {}
    for geneId, v in pairs(unlockGenes) do
        ---@type CatHouseCatDataVo
        local vo = setting:Get(geneId)
        if vo ~= nil and nil ~= vo.variationKindList then
            for i, additionId in pairs(vo.variationKindList) do
                local num = attrId2Num[additionId] or 0
                attrId2Num[additionId] = num + checkNumber(vo.variationNumList[i])
            end
        end
    end
    return attrId2Num
end


