--- 生成 定制卡牌dojo
---@param goodsId integer @ 卡牌角色id 或者 定制卡牌id（角色定制卡牌表）
---@param cardCustom table | nil @ 需要定制的属性
---@return CardDojo
function CardUtils.GenerateCustomById(goodsId, cardCustom)
    local cardId    = checkInt(goodsId)
    local goodsType = GoodsUtils.GetIdType(goodsId)
    local cardData  = nil
    if goodsType == Constants.IDType.RoleCardCustomize then
        local cardCustomizeVo = cardConfMgr:GetCustomizeCardVoById(goodsId)
        local attrCustomizeVo = cardConfMgr:GetCardRobotAttributeVo(cardCustomizeVo.effectId)
        cardId   = checkInt(attrCustomizeVo.cardId)
        cardData = {}
        -- customize data
        cardData.star         = attrCustomizeVo.star
        cardData.cardLevel    = attrCustomizeVo.cardLevel
        cardData.advanceLevel = attrCustomizeVo.advanceLevel
    end
    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(cardId)
    ---@type CardDojo
    local cardDojo = import('Game.Dojo.CardDojo').New()
    cardDojo.id              = cardId
    cardDojo.cardId          = cardId
    cardDojo.star            = 0
    cardDojo.cardLevel       = 1
    cardDojo.awakeningLevel  = 1
    cardDojo.finalSkillLevel = 1
    cardDojo.cardSkin        = cardVo.defaultSkin
    cardDojo.advanceLevel    = cardVo.startAdvLevel -- startRareLevel
    -- overwrite
    if cardData then
        for key, value in pairs(cardData) do
            cardDojo[key] = value
        end
    end
    -- cardCustom
    if cardCustom then
        for key, value in pairs(cardCustom) do
            cardDojo[key] = value
        end
    end
    if cardDojo.star > 0 then
        -- calculate skill
        local CardProgressionSkillUtils = import('Game.CardProgression.CardProgressionSkillUtils')
        local finalSkillLv, buffSkillLv = CardProgressionSkillUtils.GetFinalSkillLvAndBuffLv(cardId, cardDojo.star)
        cardDojo.finalSkillLevel = finalSkillLv
        cardDojo.awakeningLevel  = buffSkillLv
    end
    return cardDojo
end


---根据 定制角色卡牌属性表 id 显示卡牌预览
