end


---根据 定制角色卡牌属性表 id 生成卡牌数据
---@param id integer @ 定制角色卡牌属性表 id
---@return CardDojo
function CardUtils.GenerateRobotById(id)
    ---@type GetCardRobotAttributeVo
    local vo = cardConfMgr:GetCardRobotAttributeVo(id)
    local CardDojo = import("Game.Dojo.CardDojo")
    ---@type CardDojo
    local cardDojo = CardDojo.New()
    if vo == nil then
        return cardDojo
    end

    local star = vo.star
    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(vo.cardId)
    local finalSkillLevel, awakeningLevel = CardUtils.GetFinalAndBuffLvByStar(vo.cardId, star)
    cardDojo.finalSkillLevel = finalSkillLevel
    cardDojo.awakeningLevel  = awakeningLevel

    local advanceLevel = vo.advanceLevel
    ---@type RoleAdvanceLevelLimitVo
    local advanceLevelLimitVo     = cardConfMgr:GetRoleAdvanceLevelLimitVo(advanceLevel)
    cardDojo.cardSkin = advanceLevelLimitVo.rare >= Constants.RareType.UR and cardVo.urSkin or cardVo.defaultSkin
    
    return cardDojo:Fill(vo)
end


---根据星级获取大招和buff等级
function CardUtils.GetFinalAndBuffLvByStar(cardId, star)
    local starIdList = cardConfMgr:GetCardStarIdList(cardId)
    local finalSkillLevel, awakeningLevel = nil, nil
    for i = #starIdList, 1, -1 do
        local starId = starIdList[i]
        ---@type CardStarVo
        local vo       = cardConfMgr:GetCardStarVo(starId)
        local confStar = vo.star
        if star >= confStar then
            if vo.spLevel > 0 then
                finalSkillLevel = cardConfMgr:GetFinalSkillDisplayLevel(vo.spLevel)
            end
            if vo.passiveLevel > 0 then
                awakeningLevel = vo.passiveLevel
            end
            
            if finalSkillLevel and awakeningLevel then
                break
            end
        end
    end

    return finalSkillLevel or 1, awakeningLevel or 1

end

--- 计算情绪共鸣等级
---@param cardsInfo any
function CardUtils.CalculateEmotion(cardsInfo)
    local emotionNumMap = {}
    
    -- 统计各种颜色情绪的数量
    local cardComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
    for i, cardInfo in ipairs(cardsInfo) do
        local cardId = cardInfo.cardId
        if isNull(cardId) then
            if isNotNull(cardInfo.teamDojo_) then
                cardId = cardInfo.teamDojo_.cardId
            end
        end
        if isNotNull(cardId) and checkNumber(cardId) > 0 then
            ---@type CardVo
            local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
            local emotion = cardVo.attributeType
            emotionNumMap[emotion] = (emotionNumMap[emotion] or 0) + 1
        end
    end
    -- print("[情绪共鸣] 颜色统计", table.dump(emotionNumMap), debug.traceback())

    -- 查找红绿蓝3种情绪中，数量最多的数量
    local emotionId = 0
    local emotionNum = 0
    for i = 1, 3, 1 do
        local num = emotionNumMap[i] or 0
        if num > emotionNum then
            emotionId = i
            emotionNum = num
        end
    end

    -- 每张光暗情绪，相当于多加一张红绿蓝
    local lightEmotionNum = emotionNumMap[4] or 0
    local darkEmotionNum = emotionNumMap[5] or 0
    local emotionNum = emotionNum + lightEmotionNum + darkEmotionNum
    
    -- 如果没有红绿蓝情绪，默认是光共鸣
    if emotionId == 0 and emotionNum > 0 then
        emotionId = 4
    end
    
    -- 限制共鸣数量，红绿蓝情绪最多4个人共鸣，光暗最多一个人共鸣
    emotionNum = math.min(4, math.max(0, emotionNum))

    -- 计算情绪共鸣等级 （最少有2个共鸣情绪时，等级为1，等级小于1就认为没共鸣）
    local emotionBonusLevel = math.min(3, math.max(0, emotionNum - 1))

    -- 如果没触发共鸣，清除emotionId，防止有一个红色也亮的情况
    if emotionBonusLevel == 0 then
        emotionId = 0
        emotionNum = 0
    end

    local result = {
        emotionId = emotionId,
        emotionNum = emotionNum,
        emotionBonusLevel = emotionBonusLevel,
    }

    return result
end

--- 计算发生情绪共鸣的id
---@param teamDojoList any
function CardUtils.CalculateEmotionBonusDict(teamDojoList)
    if (not CardUtils.IsEmotionBonusOpened()) or
    (not CardUtils.IsEmotionBonusUnlocked()) then
        return {}   -- 没有共鸣
    end
    local result = CardUtils.CalculateEmotion(teamDojoList)
    local emotionBonusDict = {
        emotionId = result.emotionId,
        emotionNum = result.emotionNum,
    }
    return emotionBonusDict
end

--- 检查情绪是否在列表里
---@param teamDojo any
---@param emotionList any
function CardUtils.ConsumeEmotionBonusDict(teamDojo, emotionDict)
    if isNull(teamDojo) then
        return false
    end

    local cardId = teamDojo.cardId
    if isNull(cardId) then
        if isNotNull(teamDojo.teamDojo_) then
            cardId = teamDojo.teamDojo_.cardId
        end
    end
    if isNotNull(cardId) and checkNumber(cardId) > 0 then
        ---@type CardVo
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
        local emotionId = cardVo.attributeType
        if emotionId == 4 
        or emotionId == 5
        or emotionId == (emotionDict.emotionId or 0) then
            local remainNum = (emotionDict.emotionNum or 0)
            if remainNum > 0 then
                emotionDict.emotionNum = remainNum - 1
                return true
            end            
        end
    end
    return false
end

--- 情绪共鸣功能是否开启
function CardUtils.IsEmotionBonusOpened()
    local vo = CfUtils.SystemToggleVo( Constants.SystemToggleIds.Id6001)
    return isNotNull(vo) and vo.status == 1 and vo.switch == 1
end

--- 情绪共鸣功能是否解锁
function CardUtils.IsEmotionBonusUnlocked()
    local systemId = Constants.SystemToggleIds.Id6001
    return GameUtils.IsUnlockedBySystemTogId(systemId), GameUtils.GetUnlockDescrBySystemTogId(systemId)
end

--- 选卡界面是否需要显示情绪共鸣
---@param chooseCardStatus any
function CardUtils.IsUseEmotionBonus(chooseCardStatus)
    if chooseCardStatus == Constants.ChooseCardStatus.Custom
    or chooseCardStatus == Constants.ChooseCardStatus.FishAccompany
    or chooseCardStatus == Constants.ChooseCardStatus.FishHangeUp then
        return false
    end
    return true
end


do
    local EffectHeadPath = {
        Skin_UP = "Effect/prefab/ui_prefab/GachaponSkin/UIFX_GachaponSkin_%d_UP.prefab",
        Skin_Down = "Effect/prefab/ui_prefab/GachaponSkin/UIFX_GachaponSkin_%d_Down.prefab",
        Head_Material = "Effect/prefab/ui_prefab/GachaponSkin/Materials/UIFX_GachaponSkin_%d.mat"
    }
    
    ---@param skinVo CardSkinVo
    ---@param imageNode UnityEngine.RectTransform | UnityEngine.UI.RawImage @ 图片节点（推荐挂载RawImage）
    ---@param uifxUpNode UnityEngine.RectTransform @ 上特效节点
    ---@param uifxDownNode UnityEngine.RectTransform @ 下特效节点
    function CardUtils.RefreshCardSkinEffectHead(skinVo, imageNode, uifxUpNode, uifxDownNode)
        ---@type UnityEngine.UI.RawImage
        local skinImage = KTool.GetComponent(imageNode.gameObject, typeof(CS.UnityEngine.UI.RawImage))
        if isNull(skinVo) or isNull(uifxUpNode) or isNull(uifxDownNode) or isNull(skinImage) then
            return
        end

        local skinId  = checkInt(skinVo.skinId)
        local skinTag = checkInt(skinVo.tag)

        ---@type CardProgressionConstants
        local CardProgressionConstants = import('Game.CardProgression.CardProgressionConstants')
        if skinTag == CardProgressionConstants.SkinTag.Red then
            local go1 = GameUtils.LoadBundleSync(string.format(EffectHeadPath.Skin_UP, skinId), uifxUpNode.gameObject, false)
            local go2 = GameUtils.LoadBundleSync(string.format(EffectHeadPath.Skin_Down, skinId), uifxDownNode.gameObject, false)
            if isNotNull(go2) then
                local loader = ResourceModule.LoadBundleSync(string.format(EffectHeadPath.Head_Material, skinId), nil, true)
                if loader.IsSuccess then
                    loader:Retain(go2)
                    skinImage.material = loader.ResultObject
                end
                loader:Release()
            end
        else
            KTool.DestroyGameObjectChildren(uifxUpNode.gameObject, true)
            KTool.DestroyGameObjectChildren(uifxDownNode.gameObject, true)
            skinImage.material = nil
        end
    end
end


return CardUtils
